import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate, useLocation } from "react-router-dom";

const Home = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [searchTerm, setSearchTerm] = useState("");
  const [users, setUsers] = useState([]);
  const [editingUser, setEditingUser] = useState(null);
  const [editFormData, setEditFormData] = useState({ name: "", email: "" });

  useEffect(() => {
    if (location.pathname !== "/home") {
      if (!(location.state && location.state.navigation_intent)) {
        navigate("/home", { replace: true });
      }
    }
  }, [location, navigate]);

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = () => {
    const token = localStorage.getItem("token");
    axios
      .get("http://localhost:5000/api/users", {
        headers: {
          Authorization: `Bearer ${token}`
        }
      })
      .then((res) => setUsers(res.data))
      .catch((err) => console.error("Error fetching users:", err));
  };

  const handleDelete = async (id) => {
    const confirm = window.confirm("Are you sure you want to delete?");
    if (!confirm) return;
    try {
      const token = localStorage.getItem("token");
      await axios.delete(`http://localhost:5000/api/users/${id}`, {
        headers: {
          Authorization: `Bearer ${token}`
        }
      });
      fetchUsers();
    } catch (err) {
      console.error("Error deleting user:", err);
    }
  };

  const handleEdit = (userId) => {
    const user = users.find((u) => u._id === userId);
    if (!user) return;
    setEditingUser(user);
    setEditFormData({ name: user.name, email: user.email });
  };

  const handleEditChange = (e) => {
    const { name, value } = e.target;
    setEditFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleUpdate = async (e) => {
    e.preventDefault();
    try {
      const token = localStorage.getItem("token");
      await axios.put(`http://localhost:5000/api/users/${editingUser._id}`, editFormData, {
        headers: {
          Authorization: `Bearer ${token}`
        }
      });
      setEditingUser(null);
      fetchUsers();
    } catch (err) {
      console.error("Error updating user:", err);
    }
  };

  return (
    <div style={{ padding: "40px 20px", background: "#e6f2ff", minHeight: "100vh", fontFamily: "'Inter', Arial, sans-serif" }}>
      <div style={{ maxWidth: "1100px", margin: "0 auto" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "36px", flexWrap: "wrap" }}>
          <h2 style={{ fontSize: "30px", fontWeight: "bold", color: "#2c3e50" }}>REGISTERED USERS</h2>
          <input
            type="text"
            placeholder="Search..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            style={{ padding: "10px 16px", borderRadius: "8px", border: "1px solid #ccc", fontSize: "16px", width: "280px" }}
          />
        </div>

        {editingUser && (
          <div style={{ background: "#fff", padding: "30px", borderRadius: "12px", boxShadow: "0 4px 16px rgba(0,0,0,0.1)", marginBottom: "36px" }}>
            <h3 style={{ color: "#007bff", fontSize: "24px", marginBottom: "20px" }}>Edit User</h3>
            <form onSubmit={handleUpdate}>
              <div style={{ marginBottom: "16px" }}>
                <label>Name:</label>
                <input
                  type="text"
                  name="name"
                  value={editFormData.name}
                  onChange={handleEditChange}
                  style={inputStyle}
                  required
                />
              </div>
              <div style={{ marginBottom: "16px" }}>
                <label>Email:</label>
                <input
                  type="email"
                  name="email"
                  value={editFormData.email}
                  onChange={handleEditChange}
                  style={inputStyle}
                  required
                />
              </div>
              <button type="submit" style={editBtnStyle}>Save</button>
              <button onClick={() => setEditingUser(null)} type="button" style={{ ...deleteBtnStyle, marginLeft: "10px" }}>Cancel</button>
            </form>
          </div>
        )}

        <table style={{ width: "100%", background: "#fff", borderCollapse: "collapse", borderRadius: "8px", overflow: "hidden", boxShadow: "0 4px 16px rgba(0,0,0,0.08)" }}>
          <thead style={{ background: "#007bff", color: "#fff" }}>
            <tr>
              <th style={thStyle}>Sno.</th>
              <th style={thStyle}>Name</th>
              <th style={thStyle}>Email</th>
              <th style={thStyle}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {users
              .filter((u) => u.name.toLowerCase().includes(searchTerm.toLowerCase()) || u.email.toLowerCase().includes(searchTerm.toLowerCase()))
              .map((u, index) => (
                <tr key={u._id}>
                  <td style={tdStyle}>{index + 1}</td>
                  <td style={tdStyle}>{u.name}</td>
                  <td style={tdStyle}>{u.email}</td>
                  <td style={tdStyle}>
                    <button onClick={() => handleEdit(u._id)} style={editBtnStyle}>Edit</button>
                    <button onClick={() => handleDelete(u._id)} style={{ ...deleteBtnStyle, marginLeft: "10px" }}>Delete</button>
                  </td>
                </tr>
              ))}
            {users.length === 0 && (
              <tr>
                <td colSpan="4" style={{ textAlign: "center", padding: "20px", fontSize: "16px", color: "#999" }}>No users found.</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

const thStyle = {
  padding: "14px 16px",
  textAlign: "left",
  fontSize: "16px",
  fontWeight: 600
};

const tdStyle = {
  padding: "12px 16px",
  fontSize: "15px",
  color: "#333",
  borderBottom: "1px solid #f0f0f0"
};

const inputStyle = {
  width: "100%",
  padding: "10px 14px",
  borderRadius: "6px",
  border: "1.5px solid #ccc",
  fontSize: "15px",
  outline: "none"
};

const editBtnStyle = {
  padding: "8px 14px",
  background: "#3498db",
  color: "#fff",
  border: "none",
  borderRadius: "6px",
  cursor: "pointer",
  fontWeight: 500
};

const deleteBtnStyle = {
  padding: "8px 14px",
  background: "#e74c3c",
  color: "#fff",
  border: "none",
  borderRadius: "6px",
  cursor: "pointer",
  fontWeight: 500
};

export default Home;
